// Валідація структури + автентифікація відправника + анти-loop.
const SECRET = $env.INBOUND_SHARED_SECRET;
const out = [];
for (const item of $input.all()) {
  const b = item.json.body ?? item.json;
  if (SECRET && item.json.headers?.['x-intake-secret'] !== SECRET) {
    throw new Error('Невірний shared secret вебхука приймання пошти');
  }
  const messageId = String(b['Message-Id'] ?? b.message_id ?? '').trim();
  if (!messageId) throw new Error('Лист без Message-ID — дедуп неможливий, у DLQ');

  const auth = String(b['Authentication-Results'] ?? b.auth_results ?? '');
  const spf = /spf=pass/i.test(auth), dkim = /dkim=pass/i.test(auth), dmarc = /dmarc=pass/i.test(auth);

  // Анти-loop: автовідповіді й no-reply у роботу не беремо.
  const autoSubmitted = String(b['Auto-Submitted'] ?? '').toLowerCase();
  const subject = String(b.subject ?? '');
  const isAuto = (autoSubmitted && autoSubmitted !== 'no')
    || /out of office|automatic reply|автовідповідь|автоответ/i.test(subject);

  out.push({ json: {
    message_id: messageId,
    from: String(b.from ?? b.sender ?? '').toLowerCase(),
    subject,
    text: String(b['stripped-text'] ?? b.text ?? ''),
    html: String(b['stripped-html'] ?? b.html ?? ''),
    attachments: b.attachments ?? [],
    auth: { spf, dkim, dmarc, trusted: spf && dkim && dmarc },
    is_auto: isAuto
  }});
}
return out;

// Перевірка вкладень і підготовка тексту для екстракції.
const ALLOWED = { 'application/pdf': ['pdf'], 'image/jpeg': ['jpg','jpeg'], 'image/png': ['png'], 'application/xml': ['xml'], 'text/xml': ['xml'] };
const MAX_MB = 20;
const mail = $('Валідація, SPF/DKIM/DMARC, анти-loop').first().json;
const files = [], rejected = [];

for (const a of mail.attachments) {
  const ext = String(a.filename ?? '').split('.').pop().toLowerCase();
  const type = String(a.content_type ?? a.type ?? '').split(';')[0].trim();
  const mb = Number(a.size ?? 0) / 1048576;
  if (!ALLOWED[type]) { rejected.push({ f: a.filename, why: 'тип ' + type + ' не приймається' }); continue; }
  if (!ALLOWED[type].includes(ext)) { rejected.push({ f: a.filename, why: 'розширення не відповідає MIME-типу' }); continue; }
  if (mb > MAX_MB) { rejected.push({ f: a.filename, why: 'більше ' + MAX_MB + ' МБ' }); continue; }
  files.push({ filename: a.filename, type, url: a.url ?? a.link, needs_ocr: type.startsWith('image/') });
}

if (!files.length) {
  return [{ json: { ...mail, decision: 'dlq', reason: 'Жодного придатного вкладення', rejected } }];
}

// Тіло листа вже почищене провайдером (stripped-text). Додатковий проходження
// email-reply-parser робиться в сервісі extractor — тут лише обрізаємо хвости.
const body = mail.text.split(/\n-{2,}\s*(Original Message|Пересланное сообщение|Переслане повідомлення)/i)[0].trim().slice(0, 4000);

return [{ json: { ...mail, body, files, rejected, decision: 'extract' } }];

// Розбір відповіді моделі + оцінка впевненості + природний ключ.
const mail = $('Вкладення й чистка тіла').first().json;
const raw = $input.first().json;
let data;
try {
  data = JSON.parse(raw.content?.[0]?.text ?? '{}');
} catch (e) {
  return [{ json: { decision: 'dlq', reason: 'Модель повернула невалідний JSON', raw } }];
}

const need = ['doc_type','doc_number','doc_date','counterparty_edrpou','amount_total'];
const missing = need.filter(k => !data[k]);
const lines = data.lines ?? [];
const sumLines = lines.reduce((a, l) => a + Number(l.amount || 0), 0);
const base = Number(data.amount_base || 0);
const arithOk = Math.abs(sumLines - base) <= 0.02;

let confidence = 'high';
if (missing.length) confidence = 'low';
else if (!arithOk || Number(data.ocr_quality ?? 1) < 0.8) confidence = 'medium';

const key = [data.client_id ?? mail.client_id ?? 'unknown', data.counterparty_edrpou, data.doc_type, data.doc_number, data.doc_date].join('|');

return [{ json: {
  client_id: data.client_id ?? null,
  source: 'email',
  source_ref: mail.message_id,
  natural_key: key,
  doc_type: data.doc_type,
  doc_number: data.doc_number,
  doc_date: data.doc_date,
  cp_edrpou: data.counterparty_edrpou,
  cp_name: data.counterparty_name,
  amount_base: base,
  amount_vat: Number(data.amount_vat || 0),
  amount_total: Number(data.amount_total || 0),
  lines,
  confidence,
  arith_ok: arithOk,
  missing,
  trusted_sender: mail.auth.trusted,
  extracted: { channel: 'email-llm', model: 'claude-haiku-4-5', received_at: new Date().toISOString() }
}}];
